// ── Conjugation reverse-lookup: resolve any form via lemma field ──
// Lazily built on first use from dictionary entries that have a lemma.
let _conjugationCache: Record<string, string> | null = null;
function getConjugationMap(): Record<string, string> {
  if (_conjugationCache) return _conjugationCache;
  _conjugationCache = {};
  for (const [word, entry] of Object.entries(dictionary)) {
    if (entry.lemma && entry.pos === 'v') {
      _conjugationCache[word] = entry.lemma;
    }
  }
  return _conjugationCache;
}

// ── Helper: resolve without compounds ─────────────────────────
function resolveSimpleNL(w: string): DictEntry | null {
  if (dictionary[w]) return dictionary[w];

  // Irregular verb (explicit map)
  if (IRREGULAR_MAP[w]) {
    const inf = IRREGULAR_MAP[w];
    if (dictionary[inf]) return dictionary[inf];
  }

  // Conjugation reverse-lookup via lemma fields in dictionary
  const conjMap = getConjugationMap();
  if (conjMap[w]) {
    const inf = conjMap[w];
    if (dictionary[inf]) return dictionary[inf];
  }

  // Diminutive reversal
  for (const suf of ['etje', 'pje', 'kje', 'tje', 'je']) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dictionary[base]) return dictionary[base];
      if (base.length > 1 && base[base.length - 1] === base[base.length - 2]) {
        if (dictionary[base.slice(0, -1)]) return dictionary[base.slice(0, -1)];
      }
    }
  }

  // Plural stripping: -eren, -en, -'s, -s
  if (w.endsWith('eren') && w.length > 6) {
    const base = w.slice(0, -4);
    if (dictionary[base]) return dictionary[base];
    if (dictionary[base + 'e']) return dictionary[base + 'e'];
  }
  if (w.endsWith('en') && w.length > 3) {
    const base = w.slice(0, -2);
    if (dictionary[base]) return dictionary[base];
    if (base.length > 1) {
      const doubled = base + base[base.length - 1];
      if (dictionary[doubled]) return dictionary[doubled];
    }
  }
  if (w.endsWith("'s")) {
    const base = w.slice(0, -2);
    if (dictionary[base]) return dictionary[base];
  }
  if (w.endsWith('s') && w.length > 2) {
    if (dictionary[w.slice(0, -1)]) return dictionary[w.slice(0, -1)];
  }

  // Past participle: ge-...-d/t
  if (w.startsWith('ge') && w.length > 4) {
    let stem = w.slice(2);
    if (stem.endsWith('d') || stem.endsWith('t')) {
      const s2 = stem.slice(0, -1);
      if (dictionary[s2 + 'en']) return dictionary[s2 + 'en'];
      if (dictionary[s2]) return dictionary[s2];
    }
    if (stem.endsWith('en')) {
      if (dictionary[stem]) return dictionary[stem];
      if (dictionary[stem.slice(0, -2) + 'en']) return dictionary[stem.slice(0, -2) + 'en'];
    }
    if (dictionary[stem]) return dictionary[stem];
    if (dictionary[stem + 'en']) return dictionary[stem + 'en'];
  }

  // Regular verb form reversal
  if (w.endsWith('t') && w.length > 3) {
    const inf = w.slice(0, -1) + 'en';
    if (dictionary[inf]) return dictionary[inf];
  }
  for (const pastSuf of ['ten', 'den', 'te', 'de']) {
    if (w.endsWith(pastSuf) && w.length > pastSuf.length + 2) {
      const inf = w.slice(0, -pastSuf.length) + 'en';
      if (dictionary[inf]) return dictionary[inf];
    }
  }

  // Present participle: -end/-ende
  for (const suf of ['ende', 'end']) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dictionary[base + 'en']) return dictionary[base + 'en'];
      if (dictionary[base]) return dictionary[base];
    }
  }

  // Adjective -e
  if (w.endsWith('e') && w.length > 3) {
    const base = w.slice(0, -1);
    if (dictionary[base]) return dictionary[base];
    if (base.endsWith('i') && dictionary[base.slice(0, -1) + 'i']) return dictionary[base.slice(0, -1) + 'i'];
  }

  // Comparative/superlative
  for (const suf of ['ste', 'ster', 'st', 'er']) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dictionary[base]) return dictionary[base];
      if (base.length > 1 && base[base.length - 1] === base[base.length - 2]) {
        if (dictionary[base.slice(0, -1)]) return dictionary[base.slice(0, -1)];
      }
    }
  }

  // Derivational suffixes: -heid, -schap, -lijk, -ling, -ing, -atie, -iteit
  for (const suf of ['heid', 'schap', 'lijk', 'ling', 'ing', 'elijk', 'ering', 'atie', 'iteit']) {
    if (w.endsWith(suf) && w.length > suf.length + 2) {
      const base = w.slice(0, -suf.length);
      if (dictionary[base]) return dictionary[base];
      if (dictionary[base + 'en']) return dictionary[base + 'en'];
    }
  }

  return null;
}

// ── Helper: check if a Dutch word is known ────────────────────
function isKnownNL(w: string): boolean {
  if (dictionary[w]) return true;
  for (const suf of ['en', 'er', 'e', 'n', 's', 'es']) {
    if (w.endsWith(suf) && w.length > suf.length + 2 && dictionary[w.slice(0, -suf.length)]) return true;
  }
  return false;
}

// ── Helper: compound decomposition for Dutch ──────────────────
function resolveCompoundNL(w: string): DictEntry | null {
  const linkers = ['', 's', 'e', 'en', 'er', 'n'];
  for (let i = 2; i <= w.length - 2; i++) {
    const left = w.slice(0, i);
    if (!isKnownNL(left)) continue;

    for (const lk of linkers) {
      if (lk && w.slice(i, i + lk.length) !== lk) continue;
      const right = w.slice(i + lk.length);
      if (right.length < 2) continue;

      const rr = resolveSimpleNL(right);
      if (rr) return rr;

      // Suffix strip on right part
      for (const suf of ['en', 'er', 'e', 's', 'je', 'tje', 'n', 'heid', 'ing']) {
        if (right.endsWith(suf) && right.length > suf.length + 2) {
          const rstem = right.slice(0, -suf.length);
          if (dictionary[rstem]) return dictionary[rstem];
        }
      }

      // Recursive for 3-part compounds
      if (right.length >= 5) {
        const inner = resolveCompoundNL(right);
        if (inner) return inner;
      }
    }
  }
  return null;
}

// ── Main lookup function ──────────────────────────────────────
export function lookupWord(raw: string): DictEntry | null {
  let clean = raw.toLowerCase().replace(/[¿¡.,!?;:"""\u2018\u2019()—–«»\d/]/g, '').trim();
  if (!clean || clean.length < 1) return null;

  // 1. Direct / inflection / verb lookup
  const simple = resolveSimpleNL(clean);
  if (simple) return simple;

  // 2. Hyphenated compounds: split on hyphens, look up parts
  if (clean.includes('-')) {
    const parts = clean.split('-');
    for (let p = parts.length - 1; p >= 0; p--) {
      if (parts[p].length < 2) continue;
      const r = resolveSimpleNL(parts[p]);
      if (r) return r;
    }
    const joined = parts.join('');
    const jr = resolveSimpleNL(joined);
    if (jr) return jr;
    const jc = resolveCompoundNL(joined);
    if (jc) return jc;
  }

  // 3. Separable prefix verbs: aan-, af-, bij-, in-, mee-, na-, op-, uit-, voor-, over-, om-, toe-
  const sepPfx = ['aan', 'af', 'bij', 'goed', 'in', 'mee', 'na', 'op', 'uit', 'voor', 'over', 'om', 'toe', 'door', 'tegen', 'terug', 'vast', 'weg'];
  for (const pfx of sepPfx) {
    if (clean.startsWith(pfx) && clean.length > pfx.length + 2) {
      const rest = clean.slice(pfx.length);
      const r = resolveSimpleNL(rest);
      if (r) return r;
      // Try with ge- infix (e.g. uitgestrekte → uit+ge+strekt+e)
      if (rest.startsWith('ge') && rest.length > 4) {
        const inner = rest.slice(2);
        const ir = resolveSimpleNL(inner);
        if (ir) return ir;
        for (const suf of ['te', 'de', 't', 'd', 'e', 'en']) {
          if (inner.endsWith(suf) && inner.length > suf.length + 1) {
            const base = inner.slice(0, -suf.length);
            if (dictionary[base]) return dictionary[base];
            if (dictionary[base + 'en']) return dictionary[base + 'en'];
            if (dictionary[base + 'ken']) return dictionary[base + 'ken'];
          }
        }
      }
    }
  }

  // 4. Inseparable prefix verbs: be-, er-, ge-, her-, ont-, ver-
  const insepPfx = ['be', 'er', 'ge', 'her', 'ont', 'ver'];
  for (const pfx of insepPfx) {
    if (clean.startsWith(pfx) && clean.length > pfx.length + 2) {
      const rest = clean.slice(pfx.length);
      const r = resolveSimpleNL(rest);
      if (r) return r;
    }
  }

  // 5. Compound decomposition: strip inflections first, then try splitting
  const forms = [clean];
  for (const suf of ['en', 'er', 'e', 'n', 's', 'heid', 'ing']) {
    if (clean.endsWith(suf) && clean.length > suf.length + 4) {
      forms.push(clean.slice(0, -suf.length));
    }
  }

  for (const form of forms) {
    if (form.length < 4) continue;
    const cr = resolveCompoundNL(form);
    if (cr) return cr;
  }

  return null;
}

